module example.com/t4

go 1.21
EOF
cat > a.go <<'EOF'
package t4

import (
	"io"
	"os"
)

// A: param error returned
func a(e error) error {
	return e
}

// B: global error var from external pkg
func b() error {
	return io.ErrUnexpectedEOF
}

// C: local var copy of external error var
func c() error {
	e := io.EOF
	return e
}

// D: multiple assignment
func d() error {
	f, err := os.Open("x")
	if err != nil {
		return err
	}
	defer f.Close()
	return nil
}

// E: reassignment
func e() error {
	var err error
	err = os.ErrClosed
	return err
}

// F: reassignment from external call
func f() error {
	var err error
	_, err = os.Open("x")
	return err
}

// G: return via local wrapper function
func wrap(e error) error { return e }

func g() error {
	_, err := os.Open("x")
	if err != nil {
		return wrap(err)
	}
	return nil
}

// H: return err from closure
func h() error {
	f := func() error {
		_, err := os.Open("x")
		return err
	}
	return f()
}

// I: unnamed result
func i() (error) {
	_, err := os.Open("x")
	if err != nil {
		return err
	}
	return nil
}

// J: named result returned implicitly? no
func j() (err error) {
	_, e := os.Open("x")
	if e != nil {
		err = e
	}
	return
}

// K: error from external var assigned in if init
func k() error {
	if err := os.ErrDeadlineExceeded; err != nil {
		return err
	}
	return nil
}
EOF
/workspace/executable ./...; echo "EXIT $?"

