{"command": "cd /tmp/tsig && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
)

var src = `package te

type Inner interface{ Do() error }
type Outer interface{ Inner }

func f1(o Outer) error {
	return o.Do()
}

func f2(i interface{ Do2() error }) error {
	return i.Do2()
}

func f3[T interface{ Do4() error }](t T) error {
	return t.Do4()
}

func f4(i *Inner) error {
	return (*i).Do()
}
`

func q(p *types.Package) string { return p.Name() }

func main() {
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "te.go", src, parser.ParseComments)
	conf := types.Config{}
	info := types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
	}
	pkg, err := conf.Check("example.com/te", fset, []*ast.File{f}, &info)
	if err != nil {
		panic(err)
	}
	for selExpr, sel := range info.Selections {
		pos := fset.Position(selExpr.Pos())
		obj := sel.Obj()
		sig := obj.Type().(*types.Signature)
		recvVar := sig.Recv()
		recvType := recvVar.Type()
		fmt.Printf("--- line %d objString=%q\n", pos.Line, obj.String())
		fmt.Printf("    recvVar.String()=%q recvVar.Name=%q\n", recvVar.String(), recvVar.Name())
		fmt.Printf("    recvType.String()=%q TypeString(q)=%q TypeString(nil)=%q\n", recvType.String(), types.TypeString(recvType, q), types.TypeString(recvType, nil))
		if u := recvType.Underlying(); u != recvType {
			fmt.Printf("    underlying.String()=%q TypeString(q)=%q\n", u.String(), types.TypeString(u, q))
		}
		fmt.Printf("    sel.Recv().String()=%q TypeString(q)=%q\n", sel.Recv().String(), types.TypeString(sel.Recv(), q))
		if named, ok := recvType.(*types.Named); ok {
			fmt.Printf("    named obj=%q pkgname=%q\n", named.Obj().Name(), named.Obj().Pkg().Name())
		}
		_ = pkg
	}
}
EOF
timeout 120 go build -o tsig . && ./tsig"}

