package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
)

var src = `package te

import "os"

func f1() error {
	return os.Open
}

func f2() error {
	_ = os.ErrNotExist
	return nil
}

func f3() error {
	return error(nil)
}

func f4() error {
	var e error = os.ErrNotExist
	_ = e
	return e
}

func f5() error {
	return os.Getenv("x")
}

type T struct{ F func() error }

func f6(t T) error {
	return t.F()
}

type I interface{ M() error }

func f7(i I) error {
	return i.M()
}

func f8() error {
	return (*int)(nil)
}

func lg[T any](x T) error { return nil }

func f9() error {
	return lg[int](1)
}
`

func main() {
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "te.go", src, parser.ParseComments)
	conf := types.Config{Importer: importerFunc(func(path string) (*types.Package, error) { return nil, fmt.Errorf("no importer") })}
	info := types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
		Instances:  map[*ast.Ident]types.Instance{},
	}
	pkg, err := conf.Check("example.com/te", fset, []*ast.File{f}, &info)
	if err != nil {
		fmt.Println("check err:", err)
	}
	_ = pkg
	ast.Inspect(f, func(n ast.Node) bool {
		if call, ok := n.(*ast.CallExpr); ok {
			pos := fset.Position(call.Pos())
			fmt.Printf("line %d call Fun=%T:\n", pos.Line, call.Fun)
			switch fun := call.Fun.(type) {
			case *ast.SelectorExpr:
				sel := info.Selections[fun]
				if sel != nil {
					fmt.Printf("   selection kind=%v obj=%q objString=%q recvType=%q\n", sel.Kind(), sel.Obj().Name(), sel.Obj().String(), sel.Recv())
				} else {
					fmt.Printf("   no selection; Uses[Sel]=%T %v\n", info.Uses[fun.Sel], info.Uses[fun.Sel])
				}
				if tv, ok := info.Types[fun]; ok {
					fmt.Printf("   Types[Fun]=%q isType=%v\n", tv.Type.String(), tv.IsType())
				}
			case *ast.Ident:
				obj := info.Uses[fun]
				if obj == nil {
					obj = info.Defs[fun]
				}
				fmt.Printf("   Uses/Defs=%T %q\n", obj, obj)
			case *ast.IndexExpr:
				fmt.Printf("   index expr\n")
			}
		}
		return true
	})
}

