		if err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %s\n", r, err)
		}
		ifaceRegexps = append(ifaceRegexps, re)
	}

	globs := make([]Glob, 0, len(l.ignorePackageGlobs))
	for _, g := range l.ignorePackageGlobs {
		gl, err := compileGlob(g)
		if err != nil {
			var nilGlob Glob  // to reproduce "%!s(<nil>)"
			return nil, fmt.Errorf("unable to compile globs %s: %s\n", nilGlob, err)
