const eof rune = -1

func (p *globParser) next() rune {
	if p.i >= len(p.s) { return eof }
	r, size := utf8.DecodeRuneInString(p.s[p.i:])
	p.i += size
	return r
}
func (p *globParser) peek() rune {
	if p.i >= len(p.s) { return eof }
	r, _ := utf8.DecodeRuneInString(p.s[p.i:])
	return r
}
