func (p *globParser) parseAlternation() (string, error) {
	p.next() // consume '{'
	var alts []string
	for {
		alt, err := p.parseSeq(true)
		if err != nil { return "", err }
		alts = append(alts, alt)
		r := p.peek()
		if r == ',' {
			p.next()
			continue
		}
		if r == '}' {
			p.next()
			break
		}
		// eof: lenient
		break
	}
	if len(alts) == 1 { return "(?:" + alts[0] + ")" , nil }   // hmm
	return "(?:" + strings.Join(alts, "|") + ")", nil
}
