func (p *globParser) parseClass() (string, error) {
	p.next() // consume '['
	var sb strings.Builder
	sb.WriteString("[")
	negated := false
	if p.peek() == '!' {
		p.next()
		negated = true
		sb.WriteString("^")
	}
	first := true
	for {
		lo := p.next()
		if lo == eof {
			return "", errors.New("unexpected end of input")
		}
		if lo == ']' {
			if first {
				return "", errors.New("could not parse range")
			}
			break
		}
		// handle escapes
		if lo == '\\' {
			lo = p.next()
			if lo == eof {
				return "", errors.New("unexpected end of input")
			}
		}
		if p.peek() == '-' {
			p.next() // consume '-'
			hi := p.next()
			if hi == eof {
				return "", errors.New("unexpected end of input")
			}
			if hi == '\\' {
				hi = p.next()
				if hi == eof { return "", errors.New("unexpected end of input") }
			}
			if p.eof() {
				return "", errors.New("unexpected end of input")
			}
			if p.peek() != ']' {
				return "", errors.New("expected close range character")
			}
			if hi < lo {
				return "", fmt.Errorf("hi character '%c' should be greater than lo '%c'", hi, lo)
			}
			sb.WriteString(classChar(lo) + "-" + classChar(hi))
			// hmm: after a range, the loop continues; the next char should be ']' (which will break)
			first = false
			continue
		}
		sb.WriteString(classChar(lo))
		first = false
	}
	sb.WriteString("]")
	return sb.String(), nil
}
