// parseSeq parses a sequence of nodes until eof, ',' (if inAlternation), or '}' (if inAlternation).
func (p *globParser) parseSeq(inAlt bool) (string, error) {
	var sb strings.Builder
	for {
		r := p.peek()
		if r == eof {
			return sb.String(), nil
		}
		if inAlt && (r == ',' || r == '}') {
			return sb.String(), nil
		}
		switch r {
		case '*':
			p.next()
			sb.WriteString(".*")
		case '?':
			p.next()
			sb.WriteString(".")
		case '[':
			cls, err := p.parseClass()
			if err != nil { return "", err }
			sb.WriteString(cls)
		case '{':
			alt, err := p.parseAlternation()
			if err != nil { return "", err }
			sb.WriteString(alt)
		case '\\':
			p.next()
			if p.eof() {
				// trailing backslash: produce nothing
			} else {
				c := p.next()
				sb.WriteString(regexp.QuoteMeta(string(c)))
			}
		default:
			p.next()
			sb.WriteString(regexp.QuoteMeta(string(r)))
		}
	}
}
