// Package wrapcheck implements a linter which checks that errors returned from
// external packages are wrapped before being returned.
package wrapcheck

// Config holds the configuration for the wrapcheck linter.
//
// The fields are intentionally ordered alphabetically: the decode errors are
// reported sorted by name, which mirrors the behaviour of the underlying
// configuration decoder.
type Config struct {
	// ExtraIgnoreSigs is an array of strings which specify additional
	// substrings of signatures to ignore. Unlike IgnoreSigs, this option
	// extends the default set without replacing it entirely.
	ExtraIgnoreSigs []string

	// IgnoreInterfaceRegexps defines a list of regular expressions which, if
	// matched to an underlying interface name, will ignore unwrapped errors
	// returned from a function whose call is defined on the given interface.
	IgnoreInterfaceRegexps []string

	// IgnorePackageGlobs is an array of glob patterns which, if any match the
	// package of the function returning the error, will skip wrapcheck
	// analysis for this error.
	IgnorePackageGlobs []string

	// IgnoreSigRegexps is an array of strings which specify regular
	// expressions of signatures to ignore.
	IgnoreSigRegexps []string

	// IgnoreSigs is an array of strings which specify substrings of
	// signatures to ignore.
	IgnoreSigs []string

	// ReportInternalErrors determines whether wrapcheck should report errors
	// returned from inside the package.
	ReportInternalErrors bool
}

// defaultIgnoreSigs is the default set of ignored signatures.
var defaultIgnoreSigs = []string{
	".Errorf(",
	"errors.New(",
	"errors.Unwrap(",
	"errors.Join(",
	".Wrap(",
	".Wrapf(",
	".WithMessage(",
	".WithMessagef(",
	".WithStack(",
}

// DefaultConfig returns the configuration used when no configuration file is
// present.
func DefaultConfig() *Config {
	return &Config{
		IgnoreSigs: append([]string(nil), defaultIgnoreSigs...),
	}
}

// NewWrapcheck returns a linter configured by the given config.
func NewWrapcheck(cfg *Config) *Wrapcheck {
	return &Wrapcheck{
		ignoreSigs:           cfg.IgnoreSigs,
		extraIgnoreSigs:      cfg.ExtraIgnoreSigs,
		ignoreSigRegexps:     cfg.IgnoreSigRegexps,
		ignorePackageGlobs:   cfg.IgnorePackageGlobs,
		ignoreInterfaceRegexps: cfg.IgnoreInterfaceRegexps,
		reportInternalErrors: cfg.ReportInternalErrors,
	}
}
EOF
cat > wrapcheck/analyzer.go <<'EOF'
package wrapcheck

import (
	"fmt"
	"go/ast"
	"go/types"
	"regexp"
	"strings"

	"golang.org/x/tools/go/analysis"
)

const (
	// Name is the name of the analyzer.
	Name = "wrapcheck"
	// Doc is the documentation string of the analyzer.
	Doc = "Checks that errors returned from external packages are wrapped"
)

// Wrapcheck is a linter which checks that errors returned from external
// packages are wrapped during return.
type Wrapcheck struct {
	ignoreSigs             []string
	extraIgnoreSigs        []string
	ignoreSigRegexps       []string
	ignorePackageGlobs     []string
	ignoreInterfaceRegexps []string
	reportInternalErrors   bool
}

// Analyzer returns the analysis.Analyzer for wrapcheck.
func (w *Wrapcheck) Analyzer() *analysis.Analyzer {
	return &analysis.Analyzer{
		Name: Name,
		Doc:  Doc,
		Run:  w.run,
	}
}

// Diagnostic messages reported by the linter.
const (
	externalErrMsg  = "error returned from external package is unwrapped"
	internalErrMsg  = "package-internal error should be wrapped"
	interfaceErrMsg = "error returned from interface method should be wrapped"
)

func (w *Wrapcheck) run(pass *analysis.Pass) (interface{}, error) {
	sigRegexps, err := compileRegexps(w.ignoreSigRegexps)
	if err != nil {
		return nil, err
	}

	ifaceRegexps, err := compileRegexps(w.ignoreInterfaceRegexps)
	if err != nil {
		return nil, err
	}

	globs, err := compileGlobs(w.ignorePackageGlobs)
	if err != nil {
		return nil, err
	}

	sigs := make([]string, 0, len(w.ignoreSigs)+len(w.extraIgnoreSigs))
	sigs = append(sigs, w.ignoreSigs...)
	sigs = append(sigs, w.extraIgnoreSigs...)

	for _, file := range pass.Files {
		w.checkFile(pass, file, sigs, sigRegexps, ifaceRegexps, globs)
	}

	return nil, nil
}

func compileRegexps(res []string) ([]*regexp.Regexp, error) {
	if len(res) == 0 {
		return nil, nil
	}
	compiled := make([]*regexp.Regexp, 0, len(res))
	for _, re := range res {
		r, err := regexp.Compile(re)
		if err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %s\n", re, err)
		}
		compiled = append(compiled, r)
	}
	return compiled, nil
}

// checkFile analyses a single file of the package.
func (w *Wrapcheck) checkFile(
	pass *analysis.Pass,
	file *ast.File,
	sigs []string,
	sigRegexps []*regexp.Regexp,
	ifaceRegexps []*regexp.Regexp,
	globs []Glob,
) {
	// The set of error variables which are declared within this file. Only
	// those can be traced back to the call which produced them.
	declared := declaredVars(pass, file)

	// Return statements which are lexically enclosed by a function literal are
	// only checked for traced error variables.
	inFuncLit := funcLitReturns(file)

	// The signature which produced the value last assigned to a variable
	// declared in this file.
	assigned := map[types.Object]string{}

	ast.Inspect(file, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.AssignStmt:
			sig := callSig(pass, n.Rhs)
			for _, lhs := range n.Lhs {
				if obj := lhsVar(pass, lhs); obj != nil && declared[obj] {
					assigned[obj] = sig
				}
			}
		case *ast.GenDecl:
			if n.Tok.String() != "var" {
				return true
			}
			for _, spec := range n.Specs {
				val, ok := spec.(*ast.ValueSpec)
				if !ok || len(val.Values) == 0 {
					continue
				}
				sig := callSig(pass, val.Values)
				for _, name := range val.Names {
					if obj := pass.TypesInfo.Defs[name]; obj != nil {
						if _, ok := obj.(*types.Var); ok {
							assigned[obj] = sig
						}
					}
				}
			}
		case *ast.ReturnStmt:
			w.checkReturn(pass, n, assigned, declared, inFuncLit, sigs, sigRegexps, ifaceRegexps, globs)
		}
		return true
	})
}

// declaredVars returns the set of variables which are declared in file.
func declaredVars(pass *analysis.Pass, file *ast.File) map[types.Object]bool {
	declared := map[types.Object]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		ident, ok := n.(*ast.Ident)
		if !ok {
			return true
		}
		obj, ok := pass.TypesInfo.Defs[ident]
		if !ok || obj == nil {
			return true
		}
		if _, ok := obj.(*types.Var); ok {
			declared[obj] = true
		}
		return true
	})
	return declared
}

// funcLitReturns returns the set of return statements which are enclosed by a
// function literal.
func funcLitReturns(file *ast.File) map[*ast.ReturnStmt]bool {
	inFuncLit := map[*ast.ReturnStmt]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		lit, ok := n.(*ast.FuncLit)
		if !ok {
			return true
		}
		ast.Inspect(lit.Body, func(m ast.Node) bool {
			if ret, ok := m.(*ast.ReturnStmt); ok {
				inFuncLit[ret] = true
			}
			return true
		})
		return true
	})
	return inFuncLit
}

// lhsVar returns the variable which the given left hand side expression of an
// assignment refers to, if any.
func lhsVar(pass *analysis.Pass, expr ast.Expr) types.Object {
	ident, ok := expr.(*ast.Ident)
	if !ok {
		return nil
	}
	if obj, ok := pass.TypesInfo.Uses[ident]; ok && obj != nil {
		if _, ok := obj.(*types.Var); ok {
			return obj
		}
		return nil
	}
	if obj, ok := pass.TypesInfo.Defs[ident]; ok && obj != nil {
		if _, ok := obj.(*types.Var); ok {
			return obj
		}
	}
	return nil
}

// callSig returns the signature of the function called by the first right hand
// side expression, or the empty string when the expression does not call a
// function which can be identified.
func callSig(pass *analysis.Pass, rhs []ast.Expr) string {
	if len(rhs) == 0 {
		return ""
	}
	obj := callee(pass, rhs[0])
	if obj == nil {
		return ""
	}
	return obj.String()
}

// callee returns the object which identifies the function called by expr, if
// any.
func callee(pass *analysis.Pass, expr ast.Expr) types.Object {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return nil
	}
	switch fun := call.Fun.(type) {
	case *ast.SelectorExpr:
		if sel, ok := pass.TypesInfo.Selections[fun]; ok && sel.Obj() != nil {
			return sel.Obj()
		}
		return pass.TypesInfo.Uses[fun.Sel]
	case *ast.Ident:
		if obj, ok := pass.TypesInfo.Uses[fun]; ok && obj != nil {
			return obj
		}
		return pass.TypesInfo.Defs[fun]
	}
	return nil
}

// checkReturn checks the values returned by a return statement.
func (w *Wrapcheck) checkReturn(
	pass *analysis.Pass,
	ret *ast.ReturnStmt,
	assigned map[types.Object]string,
	declared map[types.Object]bool,
	inFuncLit map[*ast.ReturnStmt]bool,
	sigs []string,
	sigRegexps []*regexp.Regexp,
	ifaceRegexps []*regexp.Regexp,
	globs []Glob,
) {
	for _, result := range ret.Results {
		if call, ok := result.(*ast.CallExpr); ok {
			// A call may produce more than one value: it is checked on its own
			// and the remaining results are not inspected.
			w.checkCall(pass, call, sigs, sigRegexps, ifaceRegexps, globs)
			return
		}
		if inFuncLit[ret] {
			// Errors returned from within a function literal are only checked
			// when they can be traced back to a variable.
			continue
		}
		w.checkExpr(pass, result, assigned, sigs, sigRegexps, ifaceRegexps, globs)
	}
}

// checkCall checks the errors produced by a call expression which is returned.
func (w *Wrapcheck) checkCall(
	pass *analysis.Pass,
	call *ast.CallExpr,
	sigs []string,
	sigRegexps []*regexp.Regexp,
	ifaceRegexps []*regexp.Regexp,
	globs []Glob,
) {
	obj := callee(pass, call)
	if obj == nil {
		return
	}
	sig := obj.String()
	if ignoredSig(sig, sigs, sigRegexps) {
		return
	}
	if ignoredPackage(obj, globs) {
		return
	}

	tv, ok := pass.TypesInfo.Types[call]
	if !ok || tv.Type == nil {
		return
	}

	msg, ok := w.message(pass, obj, sig, ifaceRegexps)
	if !ok {
		return
	}

	if t, ok := tv.Type.(*types.Tuple); ok {
		for i := 0; i < t.Len(); i++ {
			if isError(t.At(i).Type()) {
				pass.Report(analysis.Diagnostic{
					Pos:     call.Pos(),
					Message: fmt.Sprintf("%s: sig: %s", msg, sig),
				})
			}
		}
		return
	}

	if isError(tv.Type) {
		pass.Report(analysis.Diagnostic{
			Pos:     call.Pos(),
			Message: fmt.Sprintf("%s: sig: %s", msg, sig),
		})
	}
}

// checkExpr checks a single returned expression which is not a call.
func (w *Wrapcheck) checkExpr(
	pass *analysis.Pass,
	expr ast.Expr,
	assigned map[types.Object]string,
	sigs []string,
	sigRegexps []*regexp.Regexp,
	ifaceRegexps []*regexp.Regexp,
	globs []Glob,
) {
	ident, ok := expr.(*ast.Ident)
	if !ok {
		return
	}
	obj, ok := pass.TypesInfo.Uses[ident]
	if !ok || obj == nil {
		return
	}
	v, ok := obj.(*types.Var)
	if !ok {
		return
	}
	_ = v

	sig, ok := assigned[obj]
	if !ok || sig == "" {
		return
	}
	if ignoredSig(sig, sigs, sigRegexps) {
		return
	}

	tv, ok := pass.TypesInfo.Types[expr]
	if !ok || tv.Type == nil || !isError(tv.Type) {
		return
	}

	// The object of the call which produced the value is required to determine
	// the package of the error and whether it is an interface method.
	src := tracedObj(pass, sig)
	if src == nil {
		return
	}

	if ignoredPackage(src, globs) {
		return
	}

	msg, ok := w.message(pass, src, sig, ifaceRegexps)
	if !ok {
		return
	}

	pass.Report(analysis.Diagnostic{
		Pos:     expr.Pos(),
		Message: fmt.Sprintf("%s: sig: %s", msg, sig),
	})
}

// message returns the message which should be reported for an error returned
// from a call to obj.
func (w *Wrapcheck) message(
	pass *analysis.Pass,
	obj types.Object,
	sig string,
	ifaceRegexps []*regexp.Regexp,
) (string, bool) {
	if isInterfaceMethod(obj) {
		if !ignoredInterface(obj, ifaceRegexps) {
			return interfaceErrMsg, true
		}
	}

	pkg := obj.Pkg()
	if pkg != nil && pkg != pass.Pkg {
		return externalErrMsg, true
	}

	if w.reportInternalErrors {
		return internalErrMsg, true
	}

	return "", false
}

// ignoredSig returns whether the given signature is ignored.
func ignoredSig(sig string, sigs []string, regexps []*regexp.Regexp) bool {
	for _, s := range sigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, re := range regexps {
		if re.MatchString(sig) {
			return true
		}
	}
	return false
}

// ignoredPackage returns whether errors returned from the package of obj are
// ignored.
func ignoredPackage(obj types.Object, globs []Glob) bool {
	pkg := obj.Pkg()
	if pkg == nil {
		return false
	}
	for _, g := range globs {
		if g.Match(pkg.Path()) {
			return true
		}
	}
	return false
}

// ignoredInterface returns whether errors returned from calls to the given
// interface method are ignored.
func ignoredInterface(obj types.Object, regexps []*regexp.Regexp) bool {
	name := interfaceName(obj)
	if name == "" {
		return false
	}
	for _, re := range regexps {
		if re.MatchString(name) {
			return true
		}
	}
	return false
}

// isInterfaceMethod returns whether obj is a method declared on an interface.
func isInterfaceMethod(obj types.Object) bool {
	fn, ok := obj.(*types.Func)
	if !ok {
		return false
	}
	sig, ok := fn.Type().(*types.Signature)
	if !ok {
		return false
	}
	recv := sig.Recv()
	if recv == nil {
		return false
	}
	t := recv.Type()
	if ptr, ok := t.(*types.Pointer); ok {
		t = ptr.Elem()
	}
	if t == nil {
		return false
	}
	_, ok = t.Underlying().(*types.Interface)
	return ok
}

// interfaceName returns the name of the interface on which the method is
// declared.
func interfaceName(obj types.Object) string {
	fn, ok := obj.(*types.Func)
	if !ok {
		return ""
	}
	sig, ok := fn.Type().(*types.Signature)
	if !ok {
		return ""
	}
	recv := sig.Recv()
	if recv == nil {
		return ""
	}
	t := recv.Type()
	if ptr, ok := t.(*types.Pointer); ok {
		t = ptr.Elem()
	}
	named, ok := t.(*types.Named)
	if !ok {
		return "interface"
	}
	typeName := named.Obj()
	if typeName == nil {
		return "interface"
	}
	if pkg := typeName.Pkg(); pkg != nil {
		return pkg.Name() + "." + typeName.Name()
	}
	return typeName.Name()
}

// tracedObj looks up the object which produced the given signature. It is used
// to determine the package and interface of errors which are returned through
// a variable.
func tracedObj(pass *analysis.Pass, sig string) types.Object {
	// The signature is the string representation of the object which produced
	// the error. There is no way to look an object up by its string
	// representation, so the object recorded alongside the signature is used
	// instead.
	return tracedObjects[sig]
}

var tracedObjects = map[string]types.Object{}

var errType = types.Universe.Lookup("error").Type()

// isError returns whether t is the error interface type.
func isError(t types.Type) bool {
	if t == nil {
		return false
	}
	return types.Identical(t, errType)
}
EOF
echo written"}

