// Package wrapcheck implements a linter which checks that errors returned from
// external packages are wrapped before being returned.
package wrapcheck

// Config holds the configuration for the wrapcheck linter.
//
// The fields are intentionally ordered alphabetically: the decode errors are
// reported sorted by name, which mirrors the behaviour of the underlying
// configuration decoder.
type Config struct {
	// ExtraIgnoreSigs is an array of strings which specify additional
	// substrings of signatures to ignore. Unlike IgnoreSigs, this option
	// extends the default set without replacing it entirely.
	ExtraIgnoreSigs []string

	// IgnoreInterfaceRegexps defines a list of regular expressions which, if
	// matched to an underlying interface name, will ignore unwrapped errors
	// returned from a function whose call is defined on the given interface.
	IgnoreInterfaceRegexps []string

	// IgnorePackageGlobs is an array of glob patterns which, if any match the
	// package of the function returning the error, will skip wrapcheck
	// analysis for this error.
	IgnorePackageGlobs []string

	// IgnoreSigRegexps is an array of strings which specify regular
	// expressions of signatures to ignore.
	IgnoreSigRegexps []string

	// IgnoreSigs is an array of strings which specify substrings of
	// signatures to ignore.
	IgnoreSigs []string

	// ReportInternalErrors determines whether wrapcheck should report errors
	// returned from inside the package.
	ReportInternalErrors bool
}

// defaultIgnoreSigs is the default set of ignored signatures.
var defaultIgnoreSigs = []string{
	".Errorf(",
	"errors.New(",
	"errors.Unwrap(",
	"errors.Join(",
	".Wrap(",
	".Wrapf(",
	".WithMessage(",
	".WithMessagef(",
	".WithStack(",
}

// DefaultConfig returns the configuration used when no configuration file is
// present.
func DefaultConfig() *Config {
	return &Config{
		IgnoreSigs: append([]string(nil), defaultIgnoreSigs...),
	}
}

// NewWrapcheck returns a linter configured by the given config.
func NewWrapcheck(cfg *Config) *Wrapcheck {
	return &Wrapcheck{
		ignoreSigs:           cfg.IgnoreSigs,
		extraIgnoreSigs:      cfg.ExtraIgnoreSigs,
		ignoreSigRegexps:     cfg.IgnoreSigRegexps,
		ignorePackageGlobs:   cfg.IgnorePackageGlobs,
		ignoreInterfaceRegexps: cfg.IgnoreInterfaceRegexps,
		reportInternalErrors: cfg.ReportInternalErrors,
	}
}
