func NewWrapcheck(cfg *Config) *Wrapcheck {
	return &Wrapcheck{
		ignoreSigs:             cfg.IgnoreSigs,
		extraIgnoreSigs:        cfg.ExtraIgnoreSigs,
		ignoreSigRegexps:       cfg.IgnoreSigRegexps,
		ignorePackageGlobs:     cfg.IgnorePackageGlobs,
		ignoreInterfaceRegexps: cfg.IgnoreInterfaceRegexps,
		reportInternalErrors:   cfg.ReportInternalErrors,
	}
}

// Analyzer returns the analysis.Analyzer for wrapcheck.
func (w *Wrapcheck) Analyzer() *analysis.Analyzer {
	return &analysis.Analyzer{
		Name: Name,
		Doc:  Doc,
		Run:  w.run,
	}
}

func (w *Wrapcheck) run(pass *analysis.Pass) (interface{}, error) {
	sigRegexps, err := compileRegexps(w.ignoreSigRegexps)
	if err != nil {
		return nil, err
	}

	ifaceRegexps, err := compileRegexps(w.ignoreInterfaceRegexps)
	if err != nil {
		return nil, err
	}

	globs, err := compileGlobs(w.ignorePackageGlobs)
	if err != nil {
		return nil, err
	}

	sigs := make([]string, 0, len(w.ignoreSigs)+len(w.extraIgnoreSigs))
	sigs = append(sigs, w.ignoreSigs...)
	sigs = append(sigs, w.extraIgnoreSigs...)

	for _, file := range pass.Files {
		w.checkFile(pass, file, sigs, sigRegexps, ifaceRegexps, globs)
	}

	return nil, nil
}

func compileRegexps(res []string) ([]*regexp.Regexp, error) {
	if len(res) == 0 {
		return nil, nil
	}
	compiled := make([]*regexp.Regexp, 0, len(res))
	for _, re := range res {
		r, err := regexp.Compile(re)
		if err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %s\n", re, err)
		}
		compiled = append(compiled, r)
	}
	return compiled, nil
}

// source identifies the call which produced an error value.
type source struct {
	obj types.Object
	sig string
}

// checkFile analyses a single file of the package.
func (w *Wrapcheck) checkFile(
	pass *analysis.Pass,
	file *ast.File,
	sigs []string,
	sigRegexps []*regexp.Regexp,
	ifaceRegexps []*regexp.Regexp,
	globs []Glob,
) {
	// The set of variables which are declared within this file. Only those can
	// be traced back to the call which produced their value.
	declared := declaredVars(pass, file)

	// Return statements which are lexically enclosed by a function literal.
	inFuncLit := funcLitReturns(file)

	// The call which produced the value last assigned to a variable declared
	// in this file.
	assigned := map[types.Object]source{}

	ast.Inspect(file, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.AssignStmt:
			src := callSource(pass, n.Rhs)
			for _, lhs := range n.Lhs {
				if obj, ok := assignVar(pass, lhs); ok && declared[obj] {
					assigned[obj] = src
				}
			}
		case *ast.GenDecl:
			if n.Tok != token.VAR {
				return true
			}
			for _, spec := range n.Specs {
				val, ok := spec.(*ast.ValueSpec)
				if !ok || len(val.Values) == 0 {
					continue
				}
				src := callSource(pass, val.Values)
				for _, name := range val.Names {
					if obj, ok := pass.TypesInfo.Defs[name]; ok && obj != nil {
						if _, ok := obj.(*types.Var); ok {
							assigned[obj] = src
						}
					}
				}
			}
		case *ast.ReturnStmt:
			w.checkReturn(pass, n, assigned, inFuncLit, sigs, sigRegexps, ifaceRegexps, globs)
		}
		return true
	})
}

// declaredVars returns the set of variables which are declared in file.
func declaredVars(pass *analysis.Pass, file *ast.File) map[types.Object]bool {
	declared := map[types.Object]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		ident, ok := n.(*ast.Ident)
		if !ok {
			return true
		}
		obj, ok := pass.TypesInfo.Defs[ident]
		if !ok || obj == nil {
			return true
		}
		if _, ok := obj.(*types.Var); ok {
			declared[obj] = true
		}
		return true
	})
	return declared
}

// funcLitReturns returns the set of return statements which are enclosed by a
// function literal.
func funcLitReturns(file *ast.File) map[*ast.ReturnStmt]bool {
	inFuncLit := map[*ast.ReturnStmt]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		lit, ok := n.(*ast.FuncLit)
		if !ok {
			return true
		}
		ast.Inspect(lit.Body, func(m ast.Node) bool {
			if ret, ok := m.(*ast.ReturnStmt); ok {
				inFuncLit[ret] = true
			}
			return true
		})
		return true
	})
	return inFuncLit
}

// assignVar returns the variable which the given left hand side expression of
// an assignment refers to.
func assignVar(pass *analysis.Pass, expr ast.Expr) (types.Object, bool) {
	ident, ok := expr.(*ast.Ident)
	if !ok {
		return nil, false
	}
	if obj, ok := pass.TypesInfo.Uses[ident]; ok && obj != nil {
		if _, ok := obj.(*types.Var); ok {
			return obj, true
		}
		return nil, false
	}
	if obj, ok := pass.TypesInfo.Defs[ident]; ok && obj != nil {
		if _, ok := obj.(*types.Var); ok {
			return obj, true
		}
	}
	return nil, false
}

// callSource returns the source of the value produced by the first right hand
// side expression.
func callSource(pass *analysis.Pass, rhs []ast.Expr) source {
	if len(rhs) == 0 {
		return source{}
	}
	obj := callee(pass, rhs[0])
	if obj == nil {
		return source{}
	}
	return source{obj: obj, sig: obj.String()}
}

// callee returns the object which identifies the function called by expr, if
// any.
func callee(pass *analysis.Pass, expr ast.Expr) types.Object {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return nil
	}
	switch fun := call.Fun.(type) {
	case *ast.SelectorExpr:
		if sel, ok := pass.TypesInfo.Selections[fun]; ok && sel.Obj() != nil {
			return sel.Obj()
		}
		return pass.TypesInfo.Uses[fun.Sel]
	case *ast.Ident:
		if obj, ok := pass.TypesInfo.Uses[fun]; ok && obj != nil {
			return obj
		}
		return pass.TypesInfo.Defs[fun]
	}
	return nil
}

// checkReturn checks the values returned by a return statement.
func (w *Wrapcheck) checkReturn(
	pass *analysis.Pass,
	ret *ast.ReturnStmt,
	assigned map[types.Object]source,
	inFuncLit map[*ast.ReturnStmt]bool,
	sigs []string,
	sigRegexps []*regexp.Regexp,
	ifaceRegexps []*regexp.Regexp,
	globs []Glob,
) {
	for _, result := range ret.Results {
		if call, ok := result.(*ast.CallExpr); ok {
			// A call may produce more than one value: it is checked on its own
			// and the remaining results of the return statement are not
			// inspected.
			if !inFuncLit[ret] {
				w.checkCall(pass, call, sigs, sigRegexps, ifaceRegexps, globs)
			}
			return
		}
		w.checkExpr(pass, result, assigned, sigs, sigRegexps, ifaceRegexps, globs)
	}
}

// checkCall checks the errors produced by a call expression which is returned.
func (w *Wrapcheck) checkCall(
	pass *analysis.Pass,
	call *ast.CallExpr,
	sigs []string,
	sigRegexps []*regexp.Regexp,
	ifaceRegexps []*regexp.Regexp,
	globs []Glob,
) {
	obj := callee(pass, call)
	if obj == nil {
		return
	}
	sig := obj.String()
	if ignoredSig(sig, sigs, sigRegexps) {
		return
	}
	if ignoredPackage(obj, globs) {
		return
	}

	tv, ok := pass.TypesInfo.Types[call]
	if !ok || tv.Type == nil {
		return
	}

	msg, ok := w.message(pass, obj, ifaceRegexps)
	if !ok {
		return
	}

	if t, ok := tv.Type.(*types.Tuple); ok {
		for i := 0; i < t.Len(); i++ {
			if isError(t.At(i).Type()) {
				pass.Report(analysis.Diagnostic{
					Pos:     call.Pos(),
					Message: fmt.Sprintf("%s: sig: %s", msg, sig),
					Category: "wrapcheck",
				})
			}
		}
		return
	}

	if isError(tv.Type) {
		pass.Report(analysis.Diagnostic{
			Pos:      call.Pos(),
			Message:  fmt.Sprintf("%s: sig: %s", msg, sig),
			Category: "wrapcheck",
		})
	}
}

// checkExpr checks a single returned expression which is not a call.
func (w *Wrapcheck) checkExpr(
	pass *analysis.Pass,
	expr ast.Expr,
	assigned map[types.Object]source,
	sigs []string,
	sigRegexps []*regexp.Regexp,
	ifaceRegexps []*regexp.Regexp,
	globs []Glob,
) {
	ident, ok := expr.(*ast.Ident)
	if !ok {
		return
	}
	obj, ok := pass.TypesInfo.Uses[ident]
	if !ok || obj == nil {
		return
	}
	if _, ok := obj.(*types.Var); !ok {
		return
	}

	src, ok := assigned[obj]
	if !ok || src.sig == "" || src.obj == nil {
		return
	}

	tv, ok := pass.TypesInfo.Types[expr]
	if !ok || tv.Type == nil || !isError(tv.Type) {
		return
	}

	if ignoredSig(src.sig, sigs, sigRegexps) {
		return
	}
	if ignoredPackage(src.obj, globs) {
		return
	}

	msg, ok := w.message(pass, src.obj, ifaceRegexps)
	if !ok {
		return
	}

	pass.Report(analysis.Diagnostic{
		Pos:      expr.Pos(),
		Message:  fmt.Sprintf("%s: sig: %s", msg, src.sig),
		Category: "wrapcheck",
	})
}

// message returns the message which should be reported for an error returned
// from a call to obj.
func (w *Wrapcheck) message(
	pass *analysis.Pass,
	obj types.Object,
	ifaceRegexps []*regexp.Regexp,
) (string, bool) {
	if isInterfaceMethod(obj) && !ignoredInterface(obj, ifaceRegexps) {
		return interfaceErrMsg, true
	}

	pkg := obj.Pkg()
	if pkg != nil && pkg != pass.Pkg {
		return externalErrMsg, true
	}

	if w.reportInternalErrors {
		return internalErrMsg, true
	}

	return "", false
}

// ignoredSig returns whether the given signature is ignored.
func ignoredSig(sig string, sigs []string, regexps []*regexp.Regexp) bool {
	for _, s := range sigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, re := range regexps {
		if re.MatchString(sig) {
			return true
		}
	}
	return false
}

// ignoredPackage returns whether errors returned from the package of obj are
// ignored.
func ignoredPackage(obj types.Object, globs []Glob) bool {
	pkg := obj.Pkg()
	if pkg == nil {
		return false
	}
	for _, g := range globs {
		if g.Match(pkg.Path()) {
			return true
		}
	}
	return false
}

// ignoredInterface returns whether errors returned from calls to the given
// interface method are ignored.
func ignoredInterface(obj types.Object, regexps []*regexp.Regexp) bool {
	name := interfaceName(obj)
	for _, re := range regexps {
		if re.MatchString(name) {
			return true
		}
	}
	return false
}

// isInterfaceMethod returns whether obj is a method declared on an interface.
func isInterfaceMethod(obj types.Object) bool {
	recv := receiver(obj)
	if recv == nil {
		return false
	}
	_, ok := recv.Underlying().(*types.Interface)
	return ok
}

// interfaceName returns the name of the interface on which the method is
// declared.
func interfaceName(obj types.Object) string {
	recv := receiver(obj)
	if recv == nil {
		return ""
	}
	named, ok := recv.(*types.Named)
	if !ok {
		return "interface"
	}
	typeName := named.Obj()
	if typeName == nil {
		return "interface"
	}
	if pkg := typeName.Pkg(); pkg != nil {
		return pkg.Name() + "." + typeName.Name()
	}
	return typeName.Name()
}

// receiver returns the type of the receiver of the function obj, if any.
func receiver(obj types.Object) types.Type {
	fn, ok := obj.(*types.Func)
	if !ok {
		return nil
	}
	sig, ok := fn.Type().(*types.Signature)
	if !ok {
		return nil
	}
	recv := sig.Recv()
	if recv == nil {
		return nil
	}
	t := recv.Type()
	if ptr, ok := t.(*types.Pointer); ok {
		t = ptr.Elem()
	}
	return t
}

var errType = types.Universe.Lookup("error").Type()

// isError returns whether t is the error interface type.
func isError(t types.Type) bool {
	if t == nil {
		return false
	}
	return types.Identical(t, errType)
}
EOF
echo ok"}

