package wrapcheck

import (
	"errors"
	"fmt"
	"regexp"
	"strings"
	"unicode/utf8"
)

// Glob matches a string against a glob pattern.
type Glob interface {
	Match(s string) bool
}

type glob struct {
	re *regexp.Regexp
}

func (g *glob) Match(s string) bool {
	return g.re.MatchString(s)
}

// compileGlobs compiles the given glob patterns.
func compileGlobs(patterns []string) ([]Glob, error) {
	if len(patterns) == 0 {
		return nil, nil
	}
	globs := make([]Glob, 0, len(patterns))
	for _, pattern := range patterns {
		g, err := compileGlob(pattern)
		if err != nil {
			var nilGlob Glob
			return nil, fmt.Errorf("unable to compile globs %s: %s\n", nilGlob, err)
		}
		globs = append(globs, g)
	}
	return globs, nil
}

// compileGlob compiles a single glob pattern into a matcher.
func compileGlob(pattern string) (Glob, error) {
	p := &globParser{src: pattern}
	expr, err := p.parseSequence(false)
	if err != nil {
		return nil, err
	}
	re, err := regexp.Compile("(?s)^(?:" + expr + ")$")
	if err != nil {
		return nil, err
	}
	return &glob{re: re}, nil
}

const eof rune = -1

// globParser parses a glob pattern into a regular expression.
type globParser struct {
	src string
	i   int
}

func (p *globParser) eof() bool {
	return p.i >= len(p.src)
}

func (p *globParser) peek() rune {
	if p.eof() {
		return eof
	}
	r, _ := utf8.DecodeRuneInString(p.src[p.i:])
	return r
}

func (p *globParser) next() rune {
	if p.eof() {
		return eof
	}
	r, size := utf8.DecodeRuneInString(p.src[p.i:])
	p.i += size
	return r
}

// parseSequence parses a sequence of pattern nodes. When inAlternation is
// true, the sequence ends at a comma or a closing brace.
func (p *globParser) parseSequence(inAlternation bool) (string, error) {
	var sb strings.Builder
	for {
		r := p.peek()
		if r == eof {
			return sb.String(), nil
		}
		if inAlternation && (r == ',' || r == '}') {
			return sb.String(), nil
		}
		switch r {
		case '*':
			p.next()
			sb.WriteString(".*")
		case '?':
			p.next()
			sb.WriteString(".")
		case '[':
			class, err := p.parseClass()
			if err != nil {
				return "", err
			}
			sb.WriteString(class)
		case '{':
			alt, err := p.parseAlternation()
			if err != nil {
				return "", err
			}
			sb.WriteString(alt)
		case '\\':
			p.next()
			if p.eof() {
				continue
			}
			c := p.next()
			sb.WriteString(regexp.QuoteMeta(string(c)))
		default:
			p.next()
			sb.WriteString(regexp.QuoteMeta(string(r)))
		}
	}
}

// parseAlternation parses a brace delimited alternation of patterns. The
// closing brace is optional.
func (p *globParser) parseAlternation() (string, error) {
	p.next() // consume '{'
	var alternatives []string
	for {
		alt, err := p.parseSequence(true)
		if err != nil {
			return "", err
		}
		alternatives = append(alternatives, alt)
		switch p.peek() {
		case ',':
			p.next()
			continue
		case '}':
			p.next()
		}
		break
	}
	return "(?:" + strings.Join(alternatives, "|") + ")", nil
}

// parseClass parses a bracket delimited character class.
func (p *globParser) parseClass() (string, error) {
	p.next() // consume '['
	var sb strings.Builder
	sb.WriteString("[")
	if p.peek() == '!' {
		p.next()
		sb.WriteString("^")
	}
	first := true
	for {
		lo := p.next()
		if lo == eof {
			return "", errors.New("unexpected end of input")
		}
		if lo == ']' {
			if first {
				return "", errors.New("could not parse range")
			}
			break
		}
		if lo == '\\' {
			lo = p.next()
			if lo == eof {
				return "", errors.New("unexpected end of input")
			}
		}
		if p.peek() != '-' {
			sb.WriteString(classChar(lo))
			first = false
			continue
		}
		p.next() // consume '-'
		hi := p.next()
		if hi == eof {
			return "", errors.New("unexpected end of input")
		}
		if hi == '\\' {
			hi = p.next()
			if hi == eof {
				return "", errors.New("unexpected end of input")
			}
		}
		if p.eof() {
			return "", errors.New("unexpected end of input")
		}
		if p.peek() != ']' {
			return "", errors.New("expected close range character")
		}
		if hi < lo {
			return "", fmt.Errorf("hi character '%c' should be greater than lo '%c'", hi, lo)
		}
		sb.WriteString(classChar(lo) + "-" + classChar(hi))
		first = false
	}
	sb.WriteString("]")
	return sb.String(), nil
}

// classChar escapes a character for use inside a character class.
func classChar(r rune) string {
	switch r {
	case '\\', ']', '[', '^':
		return "\\" + string(r)
	}
	if strings.ContainsRune(regexpSpecial, r) {
		return "\\" + string(r)
	}
	return string(r)
}

const regexpSpecial = `.+*?()|[]{}^\$`
EOF
echo ok"}

