package wrapcheck

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// configFileName is the name of the configuration file which is looked up in
// the current directory.
const configFileName = ".wrapcheck.yaml"

// LoadConfig loads the wrapcheck configuration from the configuration file in
// the current directory, if any.
func LoadConfig() (*Config, error) {
	cfg := DefaultConfig()

	info, err := os.Stat(configFileName)
	if err != nil || info.IsDir() {
		return cfg, nil
	}

	data, err := os.ReadFile(configFileName)
	if err != nil {
		return nil, fmt.Errorf("failed to parse config: %w", err)
	}

	settings := map[string]interface{}{}
	if err := yaml.Unmarshal(data, &settings); err != nil {
		return nil, fmt.Errorf("failed to parse config: While parsing config: %s", err)
	}

	insensitiviseMap(settings)

	if err := decodeConfig(settings, cfg); err != nil {
		return nil, fmt.Errorf("failed to unmarshal config: %s", err)
	}

	return cfg, nil
}

// insensitiviseMap lowercases all the keys of the given map, recursively.
func insensitiviseMap(m map[string]interface{}) {
	for key, val := range m {
		switch v := val.(type) {
		case map[string]interface{}:
			insensitiviseMap(v)
		case []interface{}:
			insensitiviseSlice(v)
		}

		lower := strings.ToLower(key)
		if key != lower {
			delete(m, key)
		}
		m[lower] = val
	}
}

// insensitiviseSlice lowercases all the keys of the maps contained in the given
// slice.
func insensitiviseSlice(a []interface{}) {
	for i, val := range a {
		switch v := val.(type) {
		case map[string]interface{}:
			insensitiviseMap(v)
			a[i] = v
		case []interface{}:
			insensitiviseSlice(v)
			a[i] = v
		}
	}
}

// decoder collects the errors which occur while decoding the configuration.
type decoder struct {
	errs []string
}

// decodeConfig decodes the given settings into cfg.
func decodeConfig(settings map[string]interface{}, cfg *Config) error {
	d := &decoder{}
	d.stringSlice("extraIgnoreSigs", settings, &cfg.ExtraIgnoreSigs)
	d.stringSlice("ignoreInterfaceRegexps", settings, &cfg.IgnoreInterfaceRegexps)
	d.stringSlice("ignorePackageGlobs", settings, &cfg.IgnorePackageGlobs)
	d.stringSlice("ignoreSigRegexps", settings, &cfg.IgnoreSigRegexps)
	d.stringSlice("ignoreSigs", settings, &cfg.IgnoreSigs)
	d.boolean("reportInternalErrors", settings, &cfg.ReportInternalErrors)

	if len(d.errs) > 0 {
		return &decodeError{errs: d.errs}
	}
	return nil
}

// decodeError is the error returned when the configuration could not be
// decoded.
type decodeError struct {
	errs []string
}

func (e *decodeError) Error() string {
	points := make([]string, len(e.errs))
	for i, err := range e.errs {
		points[i] = fmt.Sprintf("* %s", err)
	}
	sort.Strings(points)

	return fmt.Sprintf(
		"%d error(s) decoding:\n\n%s",
		len(e.errs), strings.Join(points, "\n"))
}

// stringSlice decodes the value of the given key into a slice of strings.
func (d *decoder) stringSlice(name string, settings map[string]interface{}, out *[]string) {
	raw, ok := lookup(settings, name)
	if !ok || raw == nil {
		return
	}

	// A string is split on commas (as done by the configuration library).
	if s, ok := raw.(string); ok {
		if s == "" {
			*out = []string{}
			return
		}
		*out = strings.Split(s, ",")
		return
	}

	// A map is lifted into a slice with a single element.
	var elems []interface{}
	switch v := raw.(type) {
	case []interface{}:
		elems = v
	case map[string]interface{}:
		if len(v) == 0 {
			*out = []string{}
			return
		}
		elems = []interface{}{v}
	default:
		elems = []interface{}{raw}
	}

	res := make([]string, len(elems))
	for i, e := range elems {
		s, err := decodeString(fmt.Sprintf("%s[%d]", name, i), e)
		if err != nil {
			d.errs = append(d.errs, err.Error())
			continue
		}
		res[i] = s
	}
	*out = res
}

// boolean decodes the value of the given key into a bool.
func (d *decoder) boolean(name string, settings map[string]interface{}, out *bool) {
	raw, ok := lookup(settings, name)
	if !ok || raw == nil {
		return
	}

	switch v := raw.(type) {
	case bool:
		*out = v
	case string:
		if v == "" {
			*out = false
			return
		}
		b, err := strconv.ParseBool(v)
		if err != nil {
			d.errs = append(d.errs, fmt.Sprintf("cannot parse '%s' as bool: %s", name, err))
			return
		}
		*out = b
	case int:
		*out = v != 0
	case int64:
		*out = v != 0
	case uint64:
		*out = v != 0
	case float64:
		*out = v != 0
	default:
		d.errs = append(d.errs, fmt.Sprintf(
			"'%s' expected type 'bool', got unconvertible type '%s', value: '%v'",
			name, typeName(raw), raw))
	}
}

// decodeString decodes a value into a string.
func decodeString(name string, data interface{}) (string, error) {
	if data == nil {
		return "", nil
	}

	switch v := data.(type) {
	case string:
		return v, nil
	case bool:
		if v {
			return "1", nil
		}
		return "0", nil
	case int:
		return strconv.FormatInt(int64(v), 10), nil
	case int64:
		return strconv.FormatInt(v, 10), nil
	case uint64:
		return strconv.FormatUint(v, 10), nil
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64), nil
	case []byte:
		return string(v), nil
	}

	return "", fmt.Errorf(
		"'%s' expected type 'string', got unconvertible type '%s', value: '%v'",
		name, typeName(data), data)
}

// lookup looks up the given key in the settings, case insensitively.
func lookup(settings map[string]interface{}, name string) (interface{}, bool) {
	v, ok := settings[strings.ToLower(name)]
	return v, ok
}

// typeName returns the name of the type of the given value, as it is printed in
// decode errors.
func typeName(data interface{}) string {
	switch data.(type) {
	case map[string]interface{}:
		return "map[string]interface {}"
	case []interface{}:
		return "[]interface {}"
	}
	return fmt.Sprintf("%T", data)
}
