// Command wrapcheck checks that errors returned from external packages are
// wrapped during return.
//
// The driver loads the requested packages, runs the analysis on each of them
// and reports the diagnostics which it produced, either as plain text or as
// JSON.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"go/token"
	"io"
	"log"
	"os"
	"runtime"
	"runtime/pprof"
	"runtime/trace"
	"sort"
	"strconv"
	"strings"

	"golang.org/x/tools/go/analysis"
	"golang.org/x/tools/go/analysis/checker"
	"golang.org/x/tools/go/packages"

	"wrapcheck.local/wrapcheck"
)

// The load mode required to run the analysis.
const loadMode = packages.NeedName |
	packages.NeedFiles |
	packages.NeedCompiledGoFiles |
	packages.NeedImports |
	packages.NeedTypes |
	packages.NeedTypesSizes |
	packages.NeedSyntax |
	packages.NeedTypesInfo |
	packages.NeedDeps

// flags holds the command line flags of the driver.
type flags struct {
	version    versionFlag
	all        bool
	context    int
	cpuprofile string
	debug      string
	diff       bool
	fix        bool
	printFlags bool
	json       bool
	memprofile string
	source     bool
	tags       string
	test       bool
	trace      string
	v          bool
}

// addFlags registers the driver flags on fs.
func addFlags(fs *flag.FlagSet) *flags {
	f := new(flags)
	fs.Var(&f.version, "V", "print version and exit")
	fs.BoolVar(&f.all, "all", false, "no effect (deprecated)")
	fs.IntVar(&f.context, "c", -1, "display offending line with this many lines of context")
	fs.StringVar(&f.cpuprofile, "cpuprofile", "", "write CPU profile to this file")
	fs.StringVar(&f.debug, "debug", "", `debug flags, any subset of "fpstv"`)
	fs.BoolVar(&f.diff, "diff", false, "with -fix, don't update the files, but print a unified diff")
	fs.BoolVar(&f.fix, "fix", false, "apply all suggested fixes")
	fs.BoolVar(&f.printFlags, "flags", false, "print analyzer flags in JSON")
	fs.BoolVar(&f.json, "json", false, "emit JSON output")
	fs.StringVar(&f.memprofile, "memprofile", "", "write memory profile to this file")
	fs.BoolVar(&f.source, "source", false, "no effect (deprecated)")
	fs.StringVar(&f.tags, "tags", "", "no effect (deprecated)")
	fs.BoolVar(&f.test, "test", true, "indicates whether test files should be analyzed, too")
	fs.StringVar(&f.trace, "trace", "", "write trace log to this file")
	fs.BoolVar(&f.v, "v", false, "no effect (deprecated)")
	return f
}

// versionFlag implements the -V flag protocol required by the go tool.
type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) Get() interface{} { return nil }
func (versionFlag) String() string   { return "" }

func (versionFlag) Set(s string) error {
	if s != "full" {
		log.Fatalf("unsupported flag value: -V=%s (use -V=full)", s)
	}

	printVersion(os.Stdout)
	os.Exit(0)
	return nil
}

// printVersion prints the version of the executable and its build ID.
func printVersion(w io.Writer) {
	progname, err := os.Executable()
	if err != nil {
		log.Fatal(err)
	}
	f, err := os.Open(progname)
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()

	id := sha256hex(f)
	fmt.Fprintf(w, "%s version devel comments-go-here buildID=%02x\n", progname, id)
}

func main() {
	config, err := wrapcheck.LoadConfig()
	if err != nil {
		log.Fatalf("%v", err)
	}

	// The diagnostics and driver errors are reported without a timestamp.
	log.SetFlags(0)
	log.SetPrefix(wrapcheck.Name + ": ")

	os.Exit(run(wrapcheck.NewWrapcheck(config).Analyzer()))
}

func run(analyzer *analysis.Analyzer) (exitcode int) {
	fs := flag.NewFlagSet(analyzer.Name, flag.ExitOnError)
	fs.Usage = func() { printUsage(fs, analyzer) }
	f := addFlags(fs)
	fs.Parse(os.Args[1:])

	if f.printFlags {
		printAnalyzerFlags(os.Stdout)
		return 0
	}

	args := fs.Args()
	if len(args) == 0 {
		printUsage(fs, analyzer)
		return 1
	}

	done, err := startProfiling(f)
	if err != nil {
		log.Fatal(err)
	}
	defer func() {
		if err := done(); err != nil {
			log.Print(err)
		}
	}()

	initial, err := load(args, f)
	if err != nil {
		return 1
	}

	if len(initial) == 0 {
		log.Printf("%s matched no packages", strings.Join(args, " "))
		return 1
	}

	graph, err := checker.Analyze([]*analysis.Analyzer{analyzer}, initial, &checker.Options{
		Sequential: strings.Contains(f.debug, "p"),
	})
	if err != nil {
		log.Print(err)
		return 1
	}

	return report(graph, f)
}

// load loads the packages matched by the given patterns.
func load(args []string, f *flags) ([]*packages.Package, error) {
	cfg := &packages.Config{
		Mode:  loadMode,
		Tests: f.test,
	}
	initial, err := packages.Load(cfg, args...)
	if err != nil {
		log.Print(err)
		return nil, err
	}

	for _, pkg := range initial {
		for _, err := range pkg.Errors {
			fmt.Fprintln(os.Stderr, err)
		}
	}

	return initial, nil
}

// report reports the diagnostics and errors produced by the analysis.
func report(graph *checker.Graph, f *flags) (exitcode int) {
	var (
		diagnostics int
		errors      bool
	)

	type pkgResult struct {
		diags []analysis.Diagnostic
		err   error
	}
	results := map[string]pkgResult{}

	for act := range graph.All() {
		if !act.IsRoot {
			continue
		}
		if act.Err != nil {
			errors = true
			if !f.json {
				log.Print(act.Err)
			}
			results[act.Package.ID] = pkgResult{err: act.Err}
			continue
		}
		if len(act.Diagnostics) == 0 {
			continue
		}
		diagnostics += len(act.Diagnostics)
		results[act.Package.ID] = pkgResult{diags: act.Diagnostics}
	}

	if f.json {
		printJSON(os.Stdout, graph, results)
		if errors {
			return 1
		}
		return 0
	}

	seen := map[string]bool{}
	for act := range graph.All() {
		if !act.IsRoot {
			continue
		}
		if act.Err != nil {
			continue
		}
		for _, diag := range act.Diagnostics {
			key := fmt.Sprintf("%s: %s", pos(graph, diag), diag.Message)
			if seen[key] {
				continue
			}
			seen[key] = true
			printPlain(os.Stderr, graph, diag, f.context)
		}
	}

	if errors {
		return 1
	}
	if diagnostics > 0 {
		return 3
	}
	return 0
}

func pos(graph *checker.Graph, diag analysis.Diagnostic) token.Position {
	// The file set of the package which produced the diagnostic.
	return token.Position{}
}
EOF
echo ok"}

