		dbg.logf("%s matched no packages", strings.Join(args, " "))
		return 1
	}

	dbg.logf("building graph of analysis passes")

	graph, err := checker.Analyze([]*analysis.Analyzer{analyzer}, initial, &checker.Options{
		Sequential: dbg.sequential,
	})
	if err != nil {
		log.Print(err)
		return 1
	}

	if f.fix {
		dbg.logf("applied %d fixes, updated %d files", 0, 0)
	} else {
		exitcode = report(graph, f, dbg)
	}

	if err := stop(); err != nil {
		log.Print(err)
	}

	return exitcode
}

// load loads the packages matched by the given patterns.
func load(args []string, tests bool) ([]*packages.Package, error) {
	cfg := &packages.Config{
		Mode:  loadMode,
		Tests: tests,
	}
	initial, err := packages.Load(cfg, args...)
	if err != nil {
		log.Print(err)
		return nil, err
	}

	for _, pkg := range initial {
		for _, err := range pkg.Errors {
			fmt.Fprintln(os.Stderr, err)
		}
	}

	return initial, nil
}

// report reports the results of the analysis and returns the exit code.
func report(graph *checker.Graph, f *flags, dbg *debugger) (exitcode int) {
	var (
		diagnostics int
		pkgErrors   bool
		actErrors   bool
	)

	for _, root := range graph.Roots {
		if len(root.Package.Errors) > 0 {
			pkgErrors = true
		}
	}

	if !f.json {
		for act := range graph.All() {
			if act.Err != nil {
				actErrors = true
				log.Print(act.Err)
			}
		}
	}

	if !f.json {
		seen := map[string]bool{}
		for act := range graph.All() {
			if act.Err != nil {
				continue
			}
			for _, diag := range act.Diagnostics {
				key := fmt.Sprintf("%s: %s", position(fsetOf(act), diag.Pos), diag.Message)
				if seen[key] {
					continue
				}
				seen[key] = true
				diagnostics++
				printPlain(os.Stderr, fsetOf(act), diag, f.context)
			}
		}
	}

	if f.json {
		printJSON(os.Stdout, graph)
	}

	dbg.logTiming()

	if pkgErrors || actErrors {
		return 1
	}
	if !f.json && diagnostics > 0 {
		return 3
	}
	return 0
}

// fsetOf returns the file set of the package of the action.
func fsetOf(act *checker.Action) *token.FileSet {
	return act.Package.Fset
}

// position returns the position of the given token position.
func position(fset *token.FileSet, p token.Pos) token.Position {
	if fset == nil || !p.IsValid() {
		return token.Position{}
	}
	return fset.Position(p)
}

// printPlain prints a diagnostic in plain text form.
func printPlain(w io.Writer, fset *token.FileSet, diag analysis.Diagnostic, context int) {
	posn := position(fset, diag.Pos)
	fmt.Fprintf(w, "%s: %s\n", posn, diag.Message)

	if context < 0 {
		return
	}

	filename := posn.Filename
	if filename == "" {
		return
	}
	src, err := os.ReadFile(filename)
	if err != nil {
		return
	}
	lines := strings.Split(string(src), "\n")
	for i := posn.Line - context; i <= posn.Line+context; i++ {
		if 1 <= i && i <= len(lines) {
			fmt.Fprintf(w, "%d\t%s\n", i, lines[i-1])
		}
	}
}

// printJSON prints the diagnostics in JSON form.
func printJSON(w io.Writer, graph *checker.Graph) {
	type jsonDiag struct {
		Category string `json:"category,omitempty"`
		Posn    string `json:"posn"`
		Message string `json:"message"`
	}
	type jsonAnalyzerResult struct {
		Diagnostics []jsonDiag `json:"diagnostics,omitempty"`
		Error       string     `json:"error,omitempty"`
	}
	type jsonPackage map[string]interface{}

	results := map[string]jsonPackage{}

	for act := range graph.All() {
		id := act.Package.ID
		pkg, ok := results[id]
		if !ok {
			pkg = jsonPackage{}
			results[id] = pkg
		}

		if act.Err != nil {
			pkg[act.Analyzer.Name] = jsonAnalyzerResult{Error: act.Err.Error()}
			continue
		}
		if len(act.Diagnostics) == 0 {
			continue
		}
		diags := make([]jsonDiag, 0, len(act.Diagnostics))
		for _, diag := range act.Diagnostics {
			diags = append(diags, jsonDiag{
				Posn:    position(fsetOf(act), diag.Pos).String(),
				Message: diag.Message,
			})
		}
		pkg[act.Analyzer.Name] = diags
	}

	enc := json.NewEncoder(w)
	enc.SetIndent("", "\t")
	enc.SetEscapeHTML(false)
	_ = enc.Encode(results)
}

// printAnalyzerFlags prints the analyzer flags in JSON form.
func printAnalyzerFlags(w io.Writer) {
	type jsonFlag struct {
		Name  string
		Bool  bool
		Usage string
	}
	flags := []jsonFlag{
		{"V", true, "print version and exit"},
		{"all", true, "no effect (deprecated)"},
		{"c", false, "display offending line with this many lines of context"},
		{"diff", true, "with -fix, don't update the files, but print a unified diff"},
		{"flags", true, "print analyzer flags in JSON"},
		{"json", true, "emit JSON output"},
		{"source", true, "no effect (deprecated)"},
		{"tags", false, "no effect (deprecated)"},
		{"test", true, "indicates whether test files should be analyzed, too"},
		{"v", true, "no effect (deprecated)"},
	}

	b, err := json.MarshalIndent(flags, "", "\t")
	if err != nil {
		log.Print(err)
		return
	}
	_, _ = w.Write(b)
}

// printUsage prints the usage of the driver.
func printUsage(fs *flag.FlagSet, analyzer *analysis.Analyzer) {
	fmt.Fprintf(os.Stderr, "%s: %s\n\n", analyzer.Name, analyzer.Doc)
	fmt.Fprintf(os.Stderr, "Usage: %s [-flag] [package]\n\n", analyzer.Name)
	fmt.Fprintf(os.Stderr, "\nFlags:\n")
	fs.PrintDefaults()
}

// addFlags registers the driver flags on fs.
func addFlags(fs *flag.FlagSet) *flags {
	f := new(flags)
	fs.Var(&f.version, "V", "print version and exit")
	fs.BoolVar(&f.all, "all", false, "no effect (deprecated)")
	fs.IntVar(&f.context, "c", -1, "display offending line with this many lines of context")
	fs.StringVar(&f.cpuprofile, "cpuprofile", "", "write CPU profile to this file")
	fs.StringVar(&f.debug, "debug", "", `debug flags, any subset of "fpstv"`)
	fs.BoolVar(&f.diff, "diff", false, "with -fix, don't update the files, but print a unified diff")
	fs.BoolVar(&f.fix, "fix", false, "apply all suggested fixes")
	fs.BoolVar(&f.printFlags, "flags", false, "print analyzer flags in JSON")
	fs.BoolVar(&f.json, "json", false, "emit JSON output")
	fs.StringVar(&f.memprofile, "memprofile", "", "write memory profile to this file")
	fs.BoolVar(&f.source, "source", false, "no effect (deprecated)")
	fs.StringVar(&f.tags, "tags", "", "no effect (deprecated)")
	fs.BoolVar(&f.test, "test", true, "indicates whether test files should be analyzed, too")
	fs.StringVar(&f.trace, "trace", "", "write trace log to this file")
	fs.BoolVar(&f.v, "v", false, "no effect (deprecated)")
	return f
}

// flags holds the values of the command line flags.
type flags struct {
	version    versionFlag
	all        bool
	context    int
	cpuprofile string
	debug      string
	diff       bool
	fix        bool
	printFlags bool
	json       bool
	memprofile string
	source     bool
	tags       string
	test       bool
	trace      string
	v          bool
}

// versionFlag implements the -V flag protocol required by the go tool.
type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) Get() interface{} { return nil }
func (versionFlag) String() string   { return "" }

func (versionFlag) Set(s string) error {
	if s != "full" {
		log.Fatalf("unsupported flag value: -V=%s (use -V=full)", s)
	}

	printVersion(os.Stdout)
	os.Exit(0)
	return nil
}

// printVersion prints the version of the executable and its build ID.
func printVersion(w io.Writer) {
	progname, err := os.Executable()
	if err != nil {
		log.Fatal(err)
	}
	f, err := os.Open(progname)
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()

	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		log.Fatal(err)
	}

	fmt.Fprintf(w, "%s version devel comments-go-here buildID=%02x\n", progname, h.Sum(nil))
}

// startProfiling starts the profiling requested by the flags. It returns a
// function which stops the profiling and writes the profile files.
func startProfiling(f *flags) (func() error, error) {
	stop := func() error { return nil }

	if f.cpuprofile != "" {
		file, err := os.Create(f.cpuprofile)
		if err != nil {
			return stop, err
		}
		if err := pprof.StartCPUProfile(file); err != nil {
			file.Close()
			return stop, err
		}
		prev := stop
		stop = func() error {
			pprof.StopCPUProfile()
			return file.Close()
		}
		_ = prev
	}

	if f.memprofile != "" {
		file, err := os.Create(f.memprofile)
		if err != nil {
			return stop, err
		}
		prev := stop
		stop = func() error {
			err := prev()
			if err2 := pprof.Lookup("heap").WriteTo(file, 0); err2 != nil {
				if err == nil {
					err = err2
			}
			}
			return file.Close()
		}
	}

	if f.trace != "" {
		file, err := os.Create(f.trace)
		if err != nil {
			return stop, err
		}
		if err := trace.Start(file); err != nil {
			file.Close()
			return stop, err
		}
		prev := stop
		stop = func() error {
			trace.Stop()
			err := prev()
			log.Printf("To view the trace, run:\n$ go tool trace view %s", f.trace)
			return err
		}
	}

	return stop, nil
}
