		return
	}
	d.log.Printf(format, args...)
}

// msgf logs a driver message. It is always printed.
func (d *debugger) msgf(format string, args ...interface{}) {
	d.log.Printf(format, args...)
}

// add records the duration of one unit of analysis work.
func (d *debugger) add(label string, duration time.Duration) {
	d.entries = append(d.entries, timingEntry{label: label, duration: duration})
}

// logTiming writes the timing information to stderr.
func (d *debugger) logTiming() {
	if !d.timing || len(d.entries) == 0 {
		return
	}

	if !d.sequential {
		d.msgf("Warning: times are mostly GC/scheduler noise; use -debug=tp to disable parallelism")
	}

	var max time.Duration
	for _, e := range d.entries {
		if e.duration > max {
			max = e.duration
		}
	}

	threshold := max / 8
	sort.SliceStable(d.entries, func(i, j int) bool {
		return d.entries[i].duration > d.entries[j].duration
	})

	var others time.Duration
	for _, e := range d.entries {
		if e.duration < threshold {
			others += e.duration
			continue
		}
		fmt.Fprintf(os.Stderr, "%s\t%s\n", e.duration, e.label)
	}
	if others > 0 {
		fmt.Fprintf(os.Stderr, "%s\tall others\n", others)
	}
}
