cat > m.go <<'EOF'
package v1

import (
	"errors"
	"fmt"
	"os"

	"example.com/v1/ext"
)

// A: basic
func a1() error { return ext.Fail() }

// B: chained method call
func a2() error {
	f, err := os.Open("x")
	if err != nil {
		return err
	}
	defer f.Close()
	return nil
}

// C: wrapping with fmt.Errorf
func a3() error {
	_, err := os.Open("x")
	if err != nil {
		return fmt.Errorf("wrapped: %w", err)
	}
	return nil
}

// D: interface
func a4(i ext.Iface) error { return i.Do() }

// E: internal
func helper() error { return ext.Fail() }

func a5() error { return helper() }

// F: conversion to error type
func a6() error {
	var e error = ext.StrErr("x")
	_ = e
	return e
}

// G: errors.New
func a7() error { return errors.New("x") }

// H: multiple returns
func a8() (error, error) {
	_, e1 := os.Open("x")
	_, e2 := os.Open("y")
	return e1, e2
}

// I: closure
func a9() error {
	f := func() error {
		_, err := os.Open("z")
		return err
	}
	return f()
}

// J: func var call
func a10() error { return ext.FailFn() }

// K: error var
func a11() error { return ext.FailVar }

// L: method on external type
func a12() error {
	f, _ := os.Open("x")
	defer f.Close()
	return f.Close()
}

// M: named result
func a13() (err error) {
	_, e := os.Open("x")
	err = e
	return err
}

// N: switch with init
func a14() error {
	switch err := ext.Fail(); err {
	default:
		return err
	}
}

// O: goroutine
func a15() error {
	_, err := os.Open("x")
	go func() error {
		return err
	}()
	return nil
}

// P: select
func a16() error {
	ch := make(chan error, 1)
	ch <- ext.Fail()
	select {
	case e := <-ch:
		return e
	}
}

// Q: label
func a17() error {
	_, err := os.Open("x")
loop:
	if err != nil {
		return err
	}
	_ = loop
	return nil
}

// R: struct field of error type
type S struct{ E error }

func a18() error {
	s := S{E: ext.Fail()}
	return s.E
}
EOF
