import os, random, subprocess, shutil, sys

random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 42)

# Building blocks
EXTERNAL_CALLS = [
    "ext.Fail()", "ext.Wrap(e)", "os.Open(\"x\")[1]", "errors.New(\"x\")",
    "fmt.Errorf(\"x\")", "i.Do()", "c.Get(\"k\")", "ext.FailFn()", "ext.FailVar",
    "helper()", "e", "nil", "err", "ext.StrErr(\"x\")",
]
ASSIGN_RHS = [
    "ext.Fail()", "os.Open(\"x\")", "errors.New(\"x\")", "helper()", "e", "nil",
    "ext.Wrap(e)", "ext.Fail2()", "i.Do()",
]
STMTS = [
    "if {err} != nil {{\n\t\treturn {err}\n\t}}",
    "{err} = {rhs}",
    "{err} := {rhs}",
    "_ = {rhs}",
    "for range []int{{1}} {{\n\t\treturn {err}\n\t}}",
    "switch {{\n\tcase true:\n\t\treturn {err}\n\t}}",
    "func() error {{\n\t\treturn {err}\n\t}}()",
    "defer func() {{\n\t\t_ = {err}\n\t}}()",
    "return {err}",
]

def gen_func(idx, body_seed):
    rnd = random.Random(body_seed)
    lines = [f"func f{idx}() error {{"]
    errvar = "err"
    lines.append(f"\t_, {errvar} := os.Open(\"in\")")
    for _ in range(rnd.randint(1, 4)):
        tmpl = rnd.choice(STMTS)
        s = tmpl.format(err=errvar, rhs=rnd.choice(ASSIGN_RHS))
        lines.append("\t" + s)
    lines.append("\treturn " + rnd.choice(EXTERNAL_CALLS))
    lines.append("}")
    return "\n".join(lines)

def build(seed, outdir):
    shutil.rmtree(outdir, ignore_errors=True)
    os.makedirs(outdir + "/ext")
    with open(outdir + "/go.mod", "w") as f:
        f.write("module example.com/g\n\ngo 1.21\n")
    with open(outdir + "/ext/ext.go", "w") as f:
        f.write('''package ext

// Fail returns an error.
func Fail() error { return nil }

// Wrap wraps.
func Wrap(e error) error { return e }

// Fail2 returns two errors.
func Fail2() (error, error) { return nil, nil }

// FailFn is a func var.
var FailFn func() error

// FailVar is an error var.
var FailVar error

// Iface is an interface.
type Iface interface {
\tDo() error
}

// Cache is an interface.
type Cache interface {
\tGet(k string) error
}

// StrErr is an error type.
type StrErr string

// Error implements error.
func (s StrErr) Error() string { return string(s) }
''')
    rnd = random.Random(seed)
    body = ["package g", "", 'import (', '\t"errors"', '\t"fmt"', '\t"os"', '', '\t"example.com/g/ext"', ')', '',
            "func helper() error { return nil }", "",
            "type T struct{ E error }", ""]
    n = rnd.randint(3, 12)
    for i in range(1, n+1):
        body.append(gen_func(i, seed*1000+i))
        body.append("")
    with open(outdir + "/m.go", "w") as f:
        f.write("\n".join(body) + "\n")

def run(seed, cfgs):
    outdir = "/tmp/genz"
    build(seed, outdir)
    diffs = 0
    for cfg in cfgs:
        if cfg is None:
            p = outdir + "/.wrapcheck.yaml"
            if os.path.exists(p): os.remove(p)
        else:
            with open(outdir + "/.wrapcheck.yaml", "w") as f:
                f.write(cfg)
        for args in (["./..."], ["-json", "./..."], ["-c", "1", "./..."], ["."]):
