            b = subprocess.run(["/tmp/wc-new"]+args, cwd=outdir, capture_output=True)
            ao = (a.stdout + a.stderr + f"\nEXIT={a.returncode}".encode())
            bo = (b.stdout + b.stderr + f"\nEXIT={b.returncode}".encode())
            if ao != bo:
                diffs += 1
                print(f"DIFF seed={seed} cfg={cfg!r} args={args}")
                al = ao.decode(errors="replace").splitlines()
                bl = bo.decode(errors="replace").splitlines()
                import difflib
                for line in list(difflib.unified_diff(al, bl))[:20]:
                    print("   ", line)
    return diffs

cfgs = [None, "ignoreSigs: []\n", "reportInternalErrors: true\n", "extraIgnoreSigs: [\".Open(\"]\n",
        "ignoreSigRegexps: [\"\\\\.Open\\\\(\"]\n", "ignorePackageGlobs: [\"os\"]\n",
