{"command": "mkdir -p /tmp/v12/ext && cd /tmp/v12 && cat > go.mod <<'EOF'
module example.com/v12

go 1.21
EOF
cat > ext/ext.go <<'EOF'
package ext

// Fail returns an error.
func Fail() error { return nil }
EOF
cat > m.go <<'EOF'
package v12

import "example.com/v12/ext"

// select with 2-value recv
func s1(ch chan error) error {
	select {
	case e, ok := <-ch:
		if !ok {
			return e
		}
		return nil
	}
}

// type switch with init
func s2(e error) error {
	switch x := interface{}(e).(type) {
	case error:
		return x
	}
	return nil
}

// for with init and post
func s3() error {
	for i := 0; i < 1; i++ {
		_, err := ext.Fn()
		_ = err
		if err != nil {
			return err
		}
	}
	return nil
}

// method value in return
func s4() error {
	t := T{}
	return t.M
}

type T struct{}

func (T) M() error { return ext.Fail() }

// composite literal with func lit
func s5() error {
	fns := []func() error{
		func() error {
			return ext.Fail()
		},
	}
	_ = fns
	return nil
}

// func lit as call argument
func s6() error {
	return callit(func() error {
		return ext.Fail()
	})
}

func callit(f func() error) error { return f() }

// nested func lits
func s7() error {
	_ = func() error {
		_ = func() error {
			return ext.Fail()
		}
		_, err := os_open()
		return err
	}
	return nil
}

func os_open() (*int, error) { return nil, nil }

// ident return inside deeply nested func lit
func s8() error {
	_, err := ext.Fail()
	_ = func() {
		_ = func() error {
			return err
		}
	}
	return nil
}

// return with func lit call
func s9() error {
	return func() error {
		return ext.Fail()
	}()
}

// switch with multiple returns in cases
func s10(e error) error {
	switch {
	case e != nil:
		return e
	default:
		return ext.Fail()
	}
}

// type switch assigning to error
func s11() error {
	var i interface{} = ext.Fail()
	switch e := i.(type) {
	case error:
		return e
	}
	return nil
}
EOF
/tmp/cmp.sh /tmp/v12 ./...; /tmp/cmp.sh /tmp/v12 -json ./...; printf 'reportInternalErrors: true\n' > .wrapcheck.yaml; /tmp/cmp.sh /tmp/v12 ./...; printf 'ignoreSigs: []\n' > .wrapcheck.yaml; /tmp/cmp.sh /tmp/v12 ./...; rm -f .wrapcheck.yaml"}

